<?php
require dirname(__DIR__).'/app/bootstrap.php';
$id=$_GET['id']??'';$r=false;$error='Hasil tidak ditemukan';$status=404;
if(preg_match('/^[a-f0-9]{32}$/',$id))try{$q=db()->prepare('SELECT * FROM results WHERE id=?');$q->execute([$id]);$r=$q->fetch(PDO::FETCH_ASSOC);}catch(Throwable $e){$error='Hasil belum dapat dimuat. Coba lagi nanti.';$status=503;}
if(!$r)http_response_code($status);
$isOwner=$r&&($r['owner_hash']??null)&&hash_equals($r['owner_hash'],ownerHash());
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Hasil Pengujian · Speedtest HST</title><link rel="stylesheet" href="/style.css"></head><body><header><a class="brand" href="/"><img src="/logo.png" alt="Lambang HST"><span>SPEEDTEST HST<strong>Hasil Pengujian</strong></span></a><nav><a href="/history.php">Riwayat Saya</a><a href="/">Tes Ulang ↗</a></nav></header><main><?php if(!$r):?><h1><?=h($error)?></h1><p class="intro"><a href="/">Kembali ke pengujian →</a></p><?php else:?><div class="eyebrow">HASIL SPEEDTEST</div><h1>Koneksi Anda.<br><em>Dalam angka.</em></h1><p class="intro"><?=h((new DateTimeImmutable($r['tested_at'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Asia/Makassar'))->format('d F Y · H:i:s'))?> WITA<br>ID hasil: <?=h($r['id'])?></p><section class="tester"><div class="tester-head"><span>PENGUJIAN SELESAI</span><span class="chip">● Tersimpan</span></div><div class="metrics"><?php foreach(['download'=>['↓ Download','Mbps'],'upload'=>['↑ Upload','Mbps'],'ping'=>['↔ Ping','ms'],'jitter'=>['≋ Jitter','ms']] as $k=>$label):?><div><span><?=h($label[0])?></span><strong><?=h($r[$k])?></strong><small><?=h($label[1])?></small></div><?php endforeach?></div><div class="connection-grid"><div><small>KONEKSI</small><strong><?=h(ucfirst($r['connection_mode']??'multi'))?></strong></div><div><small>◉ PENYEDIA INTERNET</small><strong><?=h($r['isp']??'Tidak tersedia pada hasil lama')?></strong><span><?=h(($isOwner||($_SESSION['admin']??false))?($r['client_ip']??'Tidak tersedia'):maskedIp($r['client_ip']))?></span></div><div><small>⌁ SERVER PENGUJIAN</small><strong><?=h($r['server_name']??'Server sebelumnya')?></strong><span><?=h($r['server_city']??'Tidak tersedia')?></span></div></div></section><div class="result-actions"><a class="pill-link" href="/">Uji Lagi ↗</a><button id="share" class="text-button">Salin Tautan Hasil</button><a href="/history.php">Riwayat Saya →</a><span id="share-status" role="status"></span></div><p class="intro">Hasil mengukur koneksi browser ke server tujuan pada waktu pengujian.<br>Tautan ini dapat dibuka siapa saja yang memilikinya. IP disamarkan untuk pengunjung lain.</p><script src="/result.js"></script><?php endif?></main></body></html>
